package org.kanger.storage.dumb2;
import java.nio.file.*;import java.util.*;import java.io.IOException;
import org.kanger.*;import org.kanger.exception.*;

/** Provider must fence old CURRENT authority and recover a genuinely advanced, unconfirmed marker. */
final class SymbolicUnconfirmedRecovery {
    private static int checks;
    private static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError(why);}
    private static Mind open(DB db,Path d,String name)throws Exception{User u=new User();u.setDatabaseDir(d.toString()+java.io.File.separator);db.init(u);Mind r=new Mind(u);u.setCurrentMind(r);Mind m=(Mind)r.useStorage(name);u.setCurrentMind(m);return m;}
    private static void close(Mind m)throws Exception{((User)m.getUser()).setCurrentMind(m.closeStorage());}
    private static void seed(Path d,String name,String text)throws Exception{DB db=new DB();Mind m=open(db,d,name);try{need(m.compile(text,null,false),"unconfirmed marker fixture");}finally{close(m);}}
    private static void run(boolean writer,SymbolicMarkerFaults.Point point)throws Exception{
        Path d=Files.createTempDirectory("unconfirmed-source-");seed(d,"Source","!marker(9);");seed(d,"Rules","!@u rel(1,u,1)->middle(u); !@u middle(u)->tail(u);");DB db=new DB();Mind m=open(db,d,"Source");Throwable primary=null;long expected;
        try{db.connectContext("Rules");db.applyConnectionCommand(m,"Rules","!$u rel(1,u,1);");if(writer)m.saveCheckedSymbolicContextConnections();SymbolicCacheFamilyInspection old=db.inspectSymbolicCacheFamily(m);Path location=old.local.location;long revision=db.getRevision(),target=db.versionHistory("Rules").getCurrentRevision();boolean advanced=point!=SymbolicMarkerFaults.Point.MOVE_FAIL_UNREADABLE;byte[] repaired=null;
            try(SymbolicMarkerFaults fault=new SymbolicMarkerFaults(ContextStore.revisionPath(location),point)){
                boolean failed=false;try{if(writer)m.writeCheckedSymbolicContextAssertion("!safe(8);",false);else m.saveCheckedSymbolicContextConnections();}catch(TransactionSettlementException error){failed=writer&&error.getOutcome()==TransactionSettlementException.Outcome.COMMITTED&&error.isReservationConsumed();}catch(IOException error){failed=!writer;}need(failed&&fault.moves==1&&fault.moved==advanced,"actual marker attempt became unconfirmed to the owning operation");repaired=fault.validMarker();if(point!=SymbolicMarkerFaults.Point.MOVE_REPORT_BAD_MARKER)need(RevisionStore.read(ContextStore.revisionPath(location))==revision+(advanced?1:0),"actual marker outcome is independently observed by the fixture");need(db.getRevision()==revision,"diagnostic cursor stays only last-confirmed until reconciliation");
                boolean fenced=false;try{db.federationSnapshot();}catch(StorageLifecycleException error){fenced=error.getErrorCode()==org.kanger.enums.StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE;}need(fenced,"unconfirmed source must not expose last-confirmed revision as CURRENT");
                fenced=false;try{m.writeCheckedSymbolicContextAssertion("!forbidden(77);",false);}catch(StorageLifecycleException error){fenced=error.getErrorCode()==org.kanger.enums.StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE;}need(fenced,"checked authoring cannot proceed on the old cursor");
                fenced=false;try{old.requireCurrentModelled(db,m);}catch(StorageLifecycleException error){fenced=error.getErrorCode()==org.kanger.enums.StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE;}need(fenced,"old model receipt cannot become CURRENT authority while the outcome is unconfirmed");
                boolean blocked=false;try{((User)m.getUser()).checkpoint(m);}catch(Exception expectedFailure){blocked=true;}need(blocked,"checkpoint must not guess while confirmation remains unavailable");DmzCandidateSession.requireSettledPhysicalQ(m);need(true,"failed recovery leaves no child reservation");
            }
            if(point==SymbolicMarkerFaults.Point.MOVE_REPORT_BAD_MARKER){Files.write(ContextStore.revisionPath(location),repaired);need(RevisionStore.read(ContextStore.revisionPath(location))==revision+1,"repair restores the exact valid marker bytes captured from this move");}
            if(point==SymbolicMarkerFaults.Point.MOVE_REPORT_UNREADABLE){
                Path manifest=RevisionManifestStore.path(ContextStore.generationPath(location,revision+1));byte[] valid=Files.readAllBytes(manifest),bad=valid.clone();bad[bad.length-1]^=1;
                try{Files.write(manifest,bad);boolean rejected=false;try{((User)m.getUser()).checkpoint(m);}catch(StorageLifecycleException error){rejected=true;}need(rejected&&db.getRevision()==revision,"readable marker cannot authorize adoption of a damaged sealed generation");DmzCandidateSession.requireSettledPhysicalQ(m);need(true,"generation validation failure reserves no child");boolean fenced=false;try{db.federationSnapshot();}catch(StorageLifecycleException error){fenced=true;}need(fenced,"failed generation validation leaves CURRENT fenced");}finally{Files.write(manifest,valid);}
            }
            ((User)m.getUser()).checkpoint(m);expected=revision+1;
            if(!advanced&&!writer){need(db.getRevision()==revision&&db.federationSnapshot().hasWorkingChanges(),"known unchanged save remains an unsaved intent after checkpoint");m.saveCheckedSymbolicContextConnections();}
            need(db.getRevision()==expected,"verified recovery publishes or adopts exactly one revision without resubmission");for(ContextConnection c:db.dmzTopology())need(c.getCertificate().matches(new RevisionRef(db.getContextId(),expected),c.getTarget(),c.getCertificate().getSemanticVersion()),"working certificate follows reconciled source");need(db.versionHistory("Rules").getCurrentRevision()==target,"recovery never mutates the physical target");db.inspectSymbolicCacheFamily(m).requireCurrentModelled(db,m);need(true,"new complete family qualification works after recovery");need(m.saveCheckedSymbolicContextConnections()==expected,"checked no-op creates no duplicate after reconciliation");
        }catch(Exception|AssertionError error){primary=error;throw error;}finally{try{close(m);}catch(Exception cleanup){if(primary!=null)primary.addSuppressed(cleanup);else throw cleanup;}}
        db=new DB();m=open(db,d,"Source");try{need(db.getRevision()==expected,"reconciled revision reopens cold");Set<String> originals=new HashSet<>();for(ContextProductionInventory.Row row:ContextProductionInventory.inspect(m,db.getContextId(),expected,true,Collections.emptyList(),1000).primary)originals.add(row.origin);Set<String> wanted=new HashSet<>(Collections.singletonList("!marker(9);"));if(writer)wanted.add("!safe(8);");need(originals.equals(wanted),"exact accepted originals survive without resubmission");need(db.dmzTopology().get(0).getInitialization().equals(Collections.singletonList("!$u rel(1,u,1);")),"full private recipe survives reconciled save");}finally{close(m);}
    }
    static void runAll(boolean writer)throws Exception{System.setProperty("user.home",Files.createTempDirectory("unconfirmed-home-").toString());for(SymbolicMarkerFaults.Point point:new SymbolicMarkerFaults.Point[]{SymbolicMarkerFaults.Point.MOVE_REPORT_UNREADABLE,SymbolicMarkerFaults.Point.MOVE_FAIL_UNREADABLE,SymbolicMarkerFaults.Point.MOVE_REPORT_BAD_MARKER})run(writer,point);System.out.println((writer?"SYMBOLIC_UNCONFIRMED_NATIVE_PASS":"SYMBOLIC_UNCONFIRMED_SAVE_PASS")+" checks="+checks);}
}
